impl crate::Daemon {
    pub(crate) fn novation_snapshot_response(&self) -> String {
        serde_json::json!({"ok": true, "generation": self.generation, "novation_capabilities": mackes_profiles::launch_control_capability_descriptor(), "novation_device": self.novation_device_snapshot(), "endpoint_bindings": self.endpoint_binding_projection(), "binding_generation": self.binding_generation, "led": {"phase": self.led.diagnostics().phase, "attempted": self.led.diagnostics().attempted, "sent": self.led.diagnostics().sent, "coalesced": self.led.diagnostics().coalesced, "failed": self.led.diagnostics().failed, "retries": self.led.diagnostics().retries, "last_error": self.led.diagnostics().last_error, "target_id": self.led.diagnostics().target_id, "template": self.led.diagnostics().template, "pending_deadline_ms": self.led.diagnostics().pending_deadline_ms, "desired_indices": self.led.diagnostics().desired_indices, "pending_indices": self.led.diagnostics().pending_indices, "backend_confirmation": self.led.diagnostics().backend_confirmation, "backend_state": self.led.diagnostics().backend_state, "active_lexicon_algorithm": self.lexicon_active_algorithm, "lexicon_readback_error": self.lexicon_readback_error}}).to_string() + "\n"
    }
}
